/**
 * Writes the web UI data the native IronvaleUI module reads, straight from the TypeScript in src/.
 *
 *   npx vitest run --config native/Tools/ui-fixtures/vitest.config.ts
 *
 * Outputs (both committed, both regenerated by native/ci/check-m10a.sh, which fails on drift):
 *   native/Tools/ui-fixtures/fixtures/web-ui-fixtures.json                       test cases: inputs and the web's answers
 *   native/IronvaleKit/Sources/IronvaleUI/Generated/WebUIData.swift          runtime data: presets, bindings, tips, maps, credits
 */
import { writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { expect, it } from 'vitest';
import { BINDING_PRESETS } from '../../../src/core/input';
import {
  CONTROL_PRESETS,
  DEFAULT_SETTINGS,
  parseSettings,
  QUALITY_PRESETS,
  tierForGpu,
  type ControlPreset,
  type GraphicsSettings,
  type QualityTier,
} from '../../../src/core/settings';
import { PLAYABLE_MAPS } from '../../../src/maps/registry';
import { buildCredits, CC_BY_URL, creditSentence, type CreditAsset } from '../../../src/ui/credits-model';
import { pickNeighbour, type Box, type Direction } from '../../../src/ui/focus-nav';
import { accuracyPercent, formatClock } from '../../../src/ui/format';
import { bindingRows, keyName } from '../../../src/ui/keys';
import { applyTier, matchTier, patchGraphics, presetLabel, TIERS } from '../../../src/ui/settings-model';
import { controlTips } from '../../../src/ui/screens/loading';

const out = (relative: string): string => fileURLToPath(new URL(relative, import.meta.url));
const FIXTURES = out('./fixtures/web-ui-fixtures.json');
const SWIFT = out('../../IronvaleKit/Sources/IronvaleUI/Generated/WebUIData.swift');
const PRESETS: readonly ControlPreset[] = ['trackpad', 'mouse'];

/** Stored strings a player could have: the cases in tests/core/settings.test.ts plus edge cases for types, ranges and number formats. */
const RAW_SETTINGS: readonly (string | null)[] = [
  null,
  '',
  '{not json',
  '[1,2]',
  '42',
  '"text"',
  'null',
  '{}',
  JSON.stringify(DEFAULT_SETTINGS),
  JSON.stringify({ gameplay: { fov: 90, difficulty: 7 }, audio: { master: 0.2 } }),
  JSON.stringify({
    graphics: { tier: 'cinematic', antiAliasing: 'msaa', textures: '8k', shadowMapSize: 99999, anisotropy: 3, targetFps: 144, renderScale: 40 },
    controls: { preset: 'gamepad', sensitivity: -5, lookSmoothing: 7 },
    audio: { master: 30 },
    gameplay: { difficulty: 'nightmare', fov: 900 },
  }),
  JSON.stringify({ gameplay: { fov: 90, crosshair: false } }),
  JSON.stringify({ gameplay: { minimap: false } }),
  JSON.stringify({ gameplay: { minimap: 'no' } }),
  JSON.stringify({ controls: { preset: 'trackpad', sensitivity: 34 } }),
  JSON.stringify({ controls: { preset: 'mouse', sensitivity: 22 } }),
  JSON.stringify({ controls: { preset: 'mouse', sensitivity: 34 } }),
  JSON.stringify({ controls: { sensitivity: 34 } }),
  JSON.stringify({ controls: { preset: 7, sensitivity: 34 } }),
  JSON.stringify({ controls: 'mouse' }),
  JSON.stringify({ graphics: graphicsFor('low'), controls: CONTROL_PRESETS.mouse }),
  JSON.stringify({ graphics: { ...graphicsFor('medium'), targetFps: 120, dynamicResolution: false } }),
  JSON.stringify({ graphics: { renderScale: 0.1, detailDensity: 0.0000001, particleDensity: 1e-5 } }),
  JSON.stringify({ graphics: { renderScale: 0.3333333333333333, detailDensity: 0.123456789 } }),
  JSON.stringify({ graphics: { shadowMapSize: '2048', bloom: 1, filmGrain: 'true', textures: '2k', anisotropy: 4 } }),
  JSON.stringify({ controls: { sensitivity: 123.45, adsSensitivity: 5, invertY: true, aimAssist: -1, rawInput: 0 } }),
  JSON.stringify({ audio: { master: 0, effects: 0.55, ambience: 1.5, interface: null, hrtf: false } }),
  JSON.stringify({ gameplay: { fov: 49.5, headBob: 0.25, showHitMarkers: false, difficulty: 'elite' } }),
  JSON.stringify({ graphics: [], controls: null, audio: 3, gameplay: { extra: 1 } }),
  JSON.stringify({ unknown: { a: 1 }, audio: { master: 0.5, bogus: true } }),
  '{"graphics":{"targetFps":30.0,"anisotropy":16.0},"gameplay":{"fov":1e2}}',
  '  {"audio":{"master":0.3}}  ',
];

function graphicsFor(tier: QualityTier): GraphicsSettings {
  return { targetFps: 60, dynamicResolution: true, ...QUALITY_PRESETS[tier], tier };
}

type GraphicsPatch = Partial<Omit<GraphicsSettings, 'tier'>>;
const GRAPHICS_PATCHES: readonly GraphicsPatch[] = [
  {},
  { bloom: false },
  { targetFps: 120 },
  { dynamicResolution: false },
  { renderScale: 0.5 },
  { ...QUALITY_PRESETS.low },
  { ...QUALITY_PRESETS.ultra },
  { renderScale: 1, detailDensity: 1 },
  { shadowMapSize: 0, antiAliasing: 'none' },
];

/** Deterministic boxes for the focus-navigation cases. */
function boxCases(): { boxes: Box[]; current: number; direction: Direction; expected: number }[] {
  let seed = 12345;
  const random = (): number => {
    seed = (seed * 1103515245 + 12345) % 2147483648;
    return seed / 2147483648;
  };
  const cases: { boxes: Box[]; current: number; direction: Direction; expected: number }[] = [];
  const directions: Direction[] = ['up', 'down', 'left', 'right'];
  for (let layout = 0; layout < 40; layout++) {
    const count = 3 + Math.floor(random() * 10);
    const boxes = Array.from({ length: count }, () => ({
      left: Math.round(random() * 900),
      top: Math.round(random() * 700),
      width: 40 + Math.round(random() * 200),
      height: 24 + Math.round(random() * 40),
    }));
    for (const direction of directions) {
      const current = Math.floor(random() * count);
      cases.push({ boxes, current, direction, expected: pickNeighbour(boxes, current, direction) });
    }
  }
  // A plain grid: rows of three equal buttons.
  const grid = Array.from({ length: 9 }, (_, index) => ({ left: (index % 3) * 120, top: Math.floor(index / 3) * 48, width: 100, height: 36 }));
  for (let current = 0; current < grid.length; current++) {
    for (const direction of directions) cases.push({ boxes: grid, current, direction, expected: pickNeighbour(grid, current, direction) });
  }
  return cases;
}

function firstRunRows(): [string, string][] {
  const bindings = BINDING_PRESETS.trackpad;
  const key = (codes: readonly string[]): string => keyName(codes[0] ?? '', 'trackpad');
  return [
    ['Move', 'W A S D'],
    ['Look', 'Trackpad'],
    ['Fire', `${key(bindings.fire)} or click`],
    ['Aim', key(bindings.aim)],
    ['Jump', key(bindings.jump)],
    ['Crouch', key(bindings.crouch)],
    ['Reload', key(bindings.reload)],
    ['Weapons', `${key(bindings.slot1)} to ${key(bindings.slot4)} or two-finger scroll`],
    ['Pause', key(bindings.pause)],
  ];
}

function credits(): unknown {
  const files = import.meta.glob<{ assets: CreditAsset[] }>('../../../assets/*.json', { eager: true, import: 'default' });
  const manifest = Object.keys(files)
    .sort()
    .flatMap((path) => files[path]?.assets ?? []);
  return buildCredits(manifest).map((group) => ({
    id: group.id,
    title: group.title,
    count: group.count,
    credited: group.credited.map((line) => ({ sentence: creditSentence(line), url: line.url })),
    thanks: group.thanks,
  }));
}

it('writes the native UI fixtures and data', () => {
  const fixtures = {
    source: 'native/Tools/ui-fixtures/ui-fixtures.gen.ts',
    storageKey: 'ironvale.settings.v1',
    defaults: JSON.stringify(DEFAULT_SETTINGS),
    parse: RAW_SETTINGS.map((raw) => ({ raw, stored: JSON.stringify(parseSettings(raw)) })),
    tiers: TIERS.flatMap((from) =>
      GRAPHICS_PATCHES.map((patch) => {
        const base = graphicsFor(from);
        const patched = patchGraphics(base, patch);
        return {
          base: JSON.stringify(base),
          patch: JSON.stringify(patch),
          patched: JSON.stringify(patched),
          matchTier: matchTier(patched),
          presetLabel: presetLabel(patched),
          applied: Object.fromEntries(TIERS.map((tier) => [tier, JSON.stringify(applyTier(patched, tier))])),
        };
      }),
    ),
    gpu: ['Apple M1', 'Apple M2', 'Apple M2 Pro', 'Apple M1 Max', 'Apple M3', 'Apple M5 Max', 'Apple M10', 'Intel(R) Iris(TM) Plus Graphics 655', 'SwiftShader', 'Apple GPU', 'AMD Radeon Pro 5500M'].map(
      (name) => ({ name, tier: tierForGpu(name) }),
    ),
    focus: boxCases(),
    clock: [0, -3, Number.NaN, 59.9, 60, 61, 599, 3600, 3725.5].map((seconds) => ({ seconds: Number.isNaN(seconds) ? null : seconds, text: formatClock(seconds) })),
    accuracy: [
      [0, 0],
      [1, 3],
      [2, 3],
      [5, 4],
      [7, 9],
    ].map(([hits, shots]) => ({ hits, shots, percent: accuracyPercent(hits ?? 0, shots ?? 0) })),
  };
  writeFileSync(FIXTURES, `${JSON.stringify(fixtures, null, 2)}\n`);

  const data = {
    defaults: DEFAULT_SETTINGS,
    qualityPresets: QUALITY_PRESETS,
    controlPresets: CONTROL_PRESETS,
    tiers: TIERS,
    bindingRows: Object.fromEntries(PRESETS.map((preset) => [preset, bindingRows(BINDING_PRESETS[preset], preset)])),
    controlTips: Object.fromEntries(PRESETS.map((preset) => [preset, controlTips(BINDING_PRESETS[preset], preset)])),
    firstRunRows: firstRunRows().map(([label, keys]) => ({ label, keys })),
    maps: PLAYABLE_MAPS,
    ccByUrl: CC_BY_URL,
    credits: credits(),
  };
  const json = JSON.stringify(data);
  expect(json.includes('"#')).toBe(false);
  const swift = [
    '// Generated by native/Tools/ui-fixtures/ui-fixtures.gen.ts from src/ (core/settings.ts, core/input.ts,',
    '// ui/keys.ts, ui/screens/loading.ts, ui/credits-model.ts, maps/registry.ts, assets/*.json). Do not edit.',
    '// Regenerate: npx vitest run --config native/Tools/ui-fixtures/vitest.config.ts',
    '',
    'enum WebUIData {',
    `    static let json = #"${json}"#`,
    '}',
    '',
  ].join('\n');
  writeFileSync(SWIFT, swift);
});
